     2→
     3→import (
     4→	"encoding/json"
     5→	"fmt"
     6→)
     7→
     8→// Transcript parsing types - Gemini CLI uses JSON format for session storage
     9→// Based on transcript_path format: ~/.gemini/tmp/<hash>/chats/session-<date>-<id>.json
    10→
    11→// Message type constants for Gemini transcripts
    12→const (
    13→	MessageTypeUser   = "user"
    14→	MessageTypeGemini = "gemini"
    15→)
    16→
    17→// GeminiTranscript represents the top-level structure of a Gemini session file
    18→type GeminiTranscript struct {
    19→	Messages []GeminiMessage `json:"messages"`
    20→}
    21→
    22→// GeminiMessage represents a single message in the transcript
    23→type GeminiMessage struct {
    24→	Type      string           `json:"type"` // MessageTypeUser or MessageTypeGemini
    25→	Content   string           `json:"content,omitempty"`
    26→	ToolCalls []GeminiToolCall `json:"toolCalls,omitempty"`
    27→}
    28→
    29→// GeminiToolCall represents a tool call in a gemini message
    30→type GeminiToolCall struct {
    31→	ID     string                 `json:"id"`
    32→	Name   string                 `json:"name"`
    33→	Args   map[string]interface{} `json:"args"`
    34→	Status string                 `json:"status,omitempty"`
    35→}
    36→
    37→// ParseTranscript parses raw JSON content into a transcript structure
    38→func ParseTranscript(data []byte) (*GeminiTranscript, error) {
    39→	var transcript GeminiTranscript
    40→	if err := json.Unmarshal(data, &transcript); err != nil {
    41→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
    42→	}
    43→	return &transcript, nil
    44→}
    45→
    46→// ExtractModifiedFiles extracts files modified by tool calls from transcript data
    47→func ExtractModifiedFiles(data []byte) ([]string, error) {
    48→	transcript, err := ParseTranscript(data)
    49→	if err != nil {
    50→		return nil, err
    51→	}
    52→
    53→	return ExtractModifiedFilesFromTranscript(transcript), nil
    54→}
    55→
    56→// ExtractModifiedFilesFromTranscript extracts files from a parsed transcript
    57→func ExtractModifiedFilesFromTranscript(transcript *GeminiTranscript) []string {
    58→	fileSet := make(map[string]bool)
    59→	var files []string
    60→
    61→	for _, msg := range transcript.Messages {
    62→		// Only process gemini messages (assistant messages)
    63→		if msg.Type != MessageTypeGemini {
    64→			continue
    65→		}
    66→
    67→		// Process tool calls in this message
    68→		for _, toolCall := range msg.ToolCalls {
    69→			// Check if it's a file modification tool
    70→			isModifyTool := false
    71→			for _, name := range FileModificationTools {
    72→				if toolCall.Name == name {
    73→					isModifyTool = true
    74→					break
    75→				}
    76→			}
    77→
    78→			if !isModifyTool {
    79→				continue
    80→			}
    81→
    82→			// Extract file path from args map
    83→			var file string
    84→			if fp, ok := toolCall.Args["file_path"].(string); ok && fp != "" {
    85→				file = fp
    86→			} else if p, ok := toolCall.Args["path"].(string); ok && p != "" {
    87→				file = p
    88→			} else if fn, ok := toolCall.Args["filename"].(string); ok && fn != "" {
    89→				file = fn
    90→			}
    91→
    92→			if file != "" && !fileSet[file] {
    93→				fileSet[file] = true
    94→				files = append(files, file)
    95→			}
    96→		}
    97→	}
    98→
    99→	return files
   100→}
