   113→func ExtractLastUserPromptFromTranscript(transcript *GeminiTranscript) string {
   114→	for i := len(transcript.Messages) - 1; i >= 0; i-- {
   115→		msg := transcript.Messages[i]
   116→		if msg.Type != MessageTypeUser {
